class SyncJob
{
    void Run(BlogContext context)
    {
        // Breaking change 4: EF 9 uses parameterized queries by default for Cosmos.
        // Raw SQL using FromSqlRaw must use FormattableString or FromSqlInterpolated.
        // Also, any raw SQL referencing c.Discriminator still works because we mapped
